// RatsPilot Folgeauftrag P1 (Performance-Collector, 2026-09-01): ermittelt, welche
// (Vorgang, Plattform, Messfenster)-Kombinationen jetzt faellig sind. Faellig = Post
// existiert (xPosted=true, xPostedAt gesetzt, PostId vorhanden), das Fenster (2h/24h/72h)
// ist seit dem Post verstrichen, es liegt noch KEINE Zeile in allris_content_performance
// fuer genau diese Kombination vor, UND wir sind nicht mehr als GRACE_MS ueber dem
// Fenster hinaus (verhindert falsch beschriftete "T+2h"-Werte fuer laengst alte Posts,
// z.B. beim allerersten Lauf nach Aktivierung dieses Features - Bestandsposts vor
// Feature-Einfuehrung werden dadurch bewusst NICHT rueckwirkend nachgemessen).
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function bool(v) {
  if (v === true || v === 1) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
function parseIso(v) {
  const t = Date.parse(safeStr(v));
  return Number.isFinite(t) ? t : null;
}

const WINDOWS = [
  { name: 't2h', ms: 2 * 3600 * 1000 },
  { name: 't24h', ms: 24 * 3600 * 1000 },
  { name: 't72h', ms: 72 * 3600 * 1000 }
];
const GRACE_MS = 6 * 3600 * 1000;

const PLATFORMS = [
  { key: 'facebook', postedFlag: 'facebookPosted', postedAt: 'facebookPostedAt', postId: 'facebookPostId' },
  { key: 'instagram', postedFlag: 'instagramPosted', postedAt: 'instagramPostedAt', postId: 'instagramPostId' },
  { key: 'mastodon', postedFlag: 'mastodonPosted', postedAt: 'mastodonPostedAt', postId: 'mastodonPostUrl' },
  { key: 'wordpress_golietz', postedFlag: 'wordpressPosted', postedAt: 'wordpressPostedAt', postId: 'wordpressPostId' }
];

const vorgaenge = $('Hole Vorgaenge fuer Performance').all().map(i => i.json || {});
const existing = $('Hole vorhandene Performance-Zeilen').all().map(i => i.json || {});
const doneSet = new Set(existing.map(r => safeStr(r.vorgangKey) + '|' + safeStr(r.platform) + '|' + safeStr(r.measurementWindow)));

const now = Date.now();
const candidates = [];
for (const row of vorgaenge) {
  for (const p of PLATFORMS) {
    if (!bool(row[p.postedFlag])) continue;
    const postedMs = parseIso(row[p.postedAt]);
    if (postedMs === null) continue;
    const postIdVal = safeStr(row[p.postId]);
    if (!postIdVal) continue;
    for (const w of WINDOWS) {
      const key = safeStr(row.vorgangKey) + '|' + p.key + '|' + w.name;
      if (doneSet.has(key)) continue;
      const elapsed = now - postedMs;
      if (elapsed < w.ms) continue;
      if (elapsed > w.ms + GRACE_MS) continue;
      candidates.push({
        vorgangKey: row.vorgangKey,
        vorgangsnummer: row.vorgangsnummer,
        platform: p.key,
        postId: postIdVal,
        postedAt: row[p.postedAt],
        measurementWindow: w.name,
        wordpressSlug: safeStr(row.wordpressSlug)
      });
    }
  }
}

if (candidates.length === 0) {
  return [{ json: { _noCandidates: true, platform: '' } }];
}
return candidates.map(c => ({ json: c }));

// Kombiniert zwei Quellen (beide heute 2026-09-01 live mit echten Werten bestaetigt,
// siehe allris_facebook_insights_resolved_2026-09-01): die einfachen Post-Felder
// (reactions.summary/comments.summary/shares - klare Einzelzahlen) fuer engagementPrimary/
// -Comments/-Shares, und den Insights-Metric post_clicks fuer engagementClicks. Bewusst
// NICHT post_reactions_by_type_total verwendet - dessen Ruecksgabeform (vermutlich eine
// Aufschluesselung je Reaktionstyp statt einer einzelnen Zahl) wurde nie mit echten
// Nicht-Null-Daten getestet, "keine Felder erfinden" gilt auch fuer unklare Formate.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function num(v) { const n = parseFloat(v); return Number.isFinite(n) ? n : null; }

const cand = $('Loop Kandidaten').item.json;
const basis = $('Hole FB Basisfelder').item.json || {};
const insights = $json || {};
const basisErrored = !!basis.error;
const insightsErrored = !!insights.error;
const data = Array.isArray(insights.data) ? insights.data : [];
function metricValue(name) {
  const m = data.find(d => d.name === name);
  if (!m || !Array.isArray(m.values) || !m.values.length) return null;
  return num(m.values[0].value);
}

return [{ json: {
  ...cand,
  _apiError: basisErrored && insightsErrored,
  engagementPrimary: basisErrored ? null : num(basis.reactions && basis.reactions.summary && basis.reactions.summary.total_count),
  engagementComments: basisErrored ? null : num(basis.comments && basis.comments.summary && basis.comments.summary.total_count),
  engagementShares: basisErrored ? null : num(basis.shares && basis.shares.count),
  engagementClicks: insightsErrored ? null : metricValue('post_clicks'),
  reach: null,
  views: null,
  saved: null,
  profileVisits: null,
  rawJson: JSON.stringify({ basis, insights })
} }];

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function num(v) { const n = parseFloat(v); return Number.isFinite(n) ? n : null; }

const cand = $('Loop Kandidaten').item.json;
const res = $json || {};
const errored = !!res.error;
const data = Array.isArray(res.data) ? res.data : [];
function metricValue(name) {
  const m = data.find(d => d.name === name);
  if (!m || !Array.isArray(m.values) || !m.values.length) return null;
  return num(m.values[0].value);
}

return [{ json: {
  ...cand,
  _apiError: errored,
  engagementPrimary: errored ? null : metricValue('likes'),
  engagementComments: errored ? null : metricValue('comments'),
  engagementShares: null,
  engagementClicks: null,
  reach: errored ? null : metricValue('reach'),
  views: errored ? null : metricValue('views'),
  saved: errored ? null : metricValue('saved'),
  profileVisits: errored ? null : metricValue('profile_visits'),
  rawJson: JSON.stringify(res)
} }];

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function num(v) { const n = parseFloat(v); return Number.isFinite(n) ? n : null; }

const cand = $('Loop Kandidaten').item.json;
const res = $json || {};
const errored = !res || !('id' in res);

return [{ json: {
  ...cand,
  _apiError: errored,
  engagementPrimary: errored ? null : num(res.favourites_count),
  engagementComments: errored ? null : num(res.replies_count),
  engagementShares: errored ? null : num(res.reblogs_count),
  engagementClicks: null,
  reach: null,
  views: null,
  saved: null,
  profileVisits: null,
  rawJson: JSON.stringify(res)
} }];

// Statify liefert KEINE per-ID-Abfrage, sondern eine Gesamtliste aller URLs mit
// Aufrufzahlen (einmal pro Lauf via "Hole WP Statify Stats" geholt, siehe dort). Wir
// suchen die passende Zeile ueber den Pfad-Teil der URL, der auf wordpressSlug endet.
// Kein Treffer (z.B. noch nicht in Statifys Liste erschienen) -> _apiError, wird beim
// naechsten Lauf innerhalb der Karenzzeit erneut versucht statt eine falsche 0 zu schreiben.
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function num(v) { const n = parseFloat(v); return Number.isFinite(n) ? n : null; }

const cand = $('Loop Kandidaten').item.json;
const slug = safeStr(cand.wordpressSlug);
const statRows = $('Hole WP Statify Stats').all().map(i => i.json || {});

let match = null;
if (slug) {
  match = statRows.find(r => {
    const path = safeStr(r.url).replace(/\/+$/, '');
    return path.endsWith('/' + slug) || path === slug;
  }) || null;
}

return [{ json: {
  ...cand,
  _apiError: !match,
  engagementPrimary: null,
  engagementComments: null,
  engagementShares: null,
  engagementClicks: null,
  reach: null,
  views: match ? num(match.count) : null,
  saved: null,
  profileVisits: null,
  rawJson: match ? JSON.stringify(match) : ''
} }];
